package tui

import (
	"fmt"
	"strings"
	"unicode/utf8"

	"charm.land/bubbles/v2/textinput"
	tea "charm.land/bubbletea/v2"
	"charm.land/lipgloss/v2"
	"github.com/charmbracelet/x/ansi"
	"github.com/sahilm/fuzzy"
)

// searchModel manages an inline search bar within a pane.
type searchModel struct {
	input   textinput.Model
	active  bool
	query   string // confirmed or live query
	matches int    // number of matches found
}

func newSearchModel() searchModel {
	ti := textinput.New()
	ti.Prompt = ""
	ti.Placeholder = "type to search…"
	ti.CharLimit = 256

	styles := ti.Styles()
	styles.Focused.Placeholder = styleDim
	styles.Focused.Text = lipgloss.NewStyle().Foreground(colorFg)
	styles.Blurred.Placeholder = styleDim
	styles.Blurred.Text = lipgloss.NewStyle().Foreground(colorFg)
	ti.SetStyles(styles)

	return searchModel{input: ti}
}

// Activate enters search mode.
func (m *searchModel) Activate() tea.Cmd {
	m.active = true
	m.input.SetValue("")
	m.query = ""
	m.matches = 0
	return m.input.Focus()
}

// Deactivate exits search mode and clears the query.
func (m *searchModel) Deactivate() {
	m.active = false
	m.query = ""
	m.matches = 0
	m.input.SetValue("")
	m.input.Blur()
}

// Confirm exits search mode but keeps the query active.
func (m *searchModel) Confirm() {
	m.active = false
	m.query = m.input.Value()
	m.input.Blur()
}

// Active returns whether the search bar is actively receiving input.
func (m searchModel) Active() bool {
	return m.active
}

// Query returns the current search query (live while typing, confirmed after enter).
func (m searchModel) Query() string {
	if m.active {
		return m.input.Value()
	}
	return m.query
}

// HasQuery returns true if there's a non-empty search query.
func (m searchModel) HasQuery() bool {
	return m.Query() != ""
}

// SetMatches updates the match count display.
func (m *searchModel) SetMatches(n int) {
	m.matches = n
}

// Update handles input messages while search is active.
func (m searchModel) Update(msg tea.Msg) (searchModel, tea.Cmd) {
	var cmd tea.Cmd
	m.input, cmd = m.input.Update(msg)
	return m, cmd
}

// View renders the search bar: bordered input box + match count below.
func (m searchModel) View(width int) string {
	// Inner width accounts for border (2) + padding (2).
	innerW := max(width-4, 10)

	// Icon + text input fills the entire box.
	icon := styleAccent.Render("⌕ ")
	iconW := ansi.StringWidth(icon)
	m.input.SetWidth(max(innerW-iconW-1, 5))
	input := m.input.View()

	box := styleSearchBar.Width(innerW).Render(icon + input)

	// Subtitle line below the box: esc hint on left, match count on right.
	hint := styleDim.Render("esc to close")
	var countLabel string
	if m.HasQuery() {
		if m.matches == 1 {
			countLabel = styleDim.Render("1 match")
		} else {
			countLabel = styleDim.Render(fmt.Sprintf("%d matches", m.matches))
		}
	}
	hintW := ansi.StringWidth(hint)
	countW := ansi.StringWidth(countLabel)
	gap := width - hintW - countW - 1
	var subtitle string
	if gap > 0 {
		subtitle = hint + strings.Repeat(" ", gap) + countLabel
	} else {
		subtitle = hint
	}

	return box + "\n" + subtitle
}

// --- Fuzzy matching utilities ---

// fuzzyHighlightLines runs fuzzy matching on each line of content
// and highlights matched characters in matching lines.
func fuzzyHighlightLines(content, query string) string {
	if query == "" {
		return content
	}

	lines := strings.Split(content, "\n")
	// Strip ANSI for matching, keep original for rendering.
	stripped := make([]string, len(lines))
	for i, line := range lines {
		stripped[i] = ansi.Strip(line)
	}

	matches := fuzzy.Find(query, stripped)
	if len(matches) == 0 {
		return content
	}

	// Build a map of line index → matched char indices.
	matchMap := make(map[int][]int, len(matches))
	for _, m := range matches {
		matchMap[m.Index] = m.MatchedIndexes
	}

	for lineIdx, indices := range matchMap {
		lines[lineIdx] = highlightCharsInStyledLine(lines[lineIdx], indices)
	}

	return strings.Join(lines, "\n")
}

// fuzzyCountMatches counts lines that fuzzy-match the query.
func fuzzyCountMatches(content, query string) int {
	if query == "" {
		return 0
	}
	lines := strings.Split(content, "\n")
	stripped := make([]string, len(lines))
	for i, line := range lines {
		stripped[i] = ansi.Strip(line)
	}
	return len(fuzzy.Find(query, stripped))
}

// highlightCharsInStyledLine highlights specific plain-text character positions
// within an ANSI-styled line by walking the string and skipping escape sequences.
func highlightCharsInStyledLine(line string, indices []int) string {
	if len(indices) == 0 {
		return line
	}
	indexSet := make(map[int]bool, len(indices))
	for _, idx := range indices {
		indexSet[idx] = true
	}

	var result strings.Builder
	plainIdx := 0

	i := 0
	for i < len(line) {
		// Skip ANSI escape sequences.
		if line[i] == '\x1b' && i+1 < len(line) && line[i+1] == '[' {
			j := i + 2
			for j < len(line) && line[j] != 'm' {
				j++
			}
			if j < len(line) {
				j++ // include 'm'
			}
			result.WriteString(line[i:j])
			i = j
			continue
		}

		r, size := utf8.DecodeRuneInString(line[i:])
		if indexSet[plainIdx] {
			result.WriteString(styleSearchMatchChar.Render(string(r)))
		} else {
			result.WriteRune(r)
		}
		plainIdx++
		i += size
	}

	return result.String()
}

// highlightName renders a name with specific character indices highlighted.
func highlightName(name string, indices []int, baseStyle lipgloss.Style) string {
	if len(indices) == 0 {
		return baseStyle.Render(name)
	}
	indexSet := make(map[int]bool, len(indices))
	for _, idx := range indices {
		indexSet[idx] = true
	}
	hlStyle := baseStyle.Underline(true).Foreground(colorAccent)
	var b strings.Builder
	for i, r := range name {
		if indexSet[i] {
			b.WriteString(hlStyle.Render(string(r)))
		} else {
			b.WriteString(baseStyle.Render(string(r)))
		}
	}
	return b.String()
}

package compare

import (
	"path/filepath"
	"testing"
)

// testdataDir returns the path to the testdata directory.
// Go test sets the working directory to the package directory.
func testdataDir(t *testing.T) string {
	t.Helper()
	abs, err := filepath.Abs("testdata")
	if err != nil {
		t.Fatalf("cannot resolve testdata path: %v", err)
	}
	return abs
}

// findNode walks the tree and returns the first node matching the given path.
func findNode(root *Node, path string) *Node {
	if root.Path == path {
		return root
	}
	for _, c := range root.Children {
		if n := findNode(c, path); n != nil {
			return n
		}
	}
	return nil
}

func TestIntegration_DirectoryDiff(t *testing.T) {
	td := testdataDir(t)
	pathA := filepath.Join(td, "app-v1")
	pathB := filepath.Join(td, "app-v2")

	result, err := Compare(pathA, pathB, "")
	if err != nil {
		t.Fatalf("Compare: %v", err)
	}

	if result.Mode != "tree" {
		t.Fatalf("mode = %q, want tree", result.Mode)
	}

	// --- Summary ---
	s := result.Summary
	if s.Added != 2 {
		t.Errorf("summary.added = %d, want 2 (NewFeature binary + plist)", s.Added)
	}
	if s.Removed != 0 {
		t.Errorf("summary.removed = %d, want 0", s.Removed)
	}
	if s.Modified != 4 {
		t.Errorf("summary.modified = %d, want 4 (App binary + Core binary + Info.plist + CodeResources)", s.Modified)
	}
	if s.Unchanged != 1 {
		t.Errorf("summary.unchanged = %d, want 1 (Core Info.plist)", s.Unchanged)
	}

	// --- Individual nodes ---
	tests := []struct {
		path   string
		status DiffStatus
		kind   FileKind
		isDir  bool
	}{
		{"Payload/App.app/App", Modified, KindMachO, false},
		{"Payload/App.app/Info.plist", Modified, KindPlist, false},
		{"Payload/App.app/_CodeSignature/CodeResources", Modified, KindText, false},
		{"Payload/App.app/Frameworks/Core.framework/Core", Modified, KindMachO, false},
		{"Payload/App.app/Frameworks/Core.framework/Info.plist", Unchanged, KindPlist, false},
		{"Payload/App.app/Frameworks/NewFeature.framework", Added, KindDirectory, true},
		{"Payload/App.app/Frameworks/NewFeature.framework/NewFeature", Added, KindMachO, false},
		{"Payload/App.app/Frameworks/NewFeature.framework/Info.plist", Added, KindPlist, false},
		// Directory status propagation
		{"Payload/App.app", Modified, KindDirectory, true},
		{"Payload/App.app/Frameworks", Modified, KindDirectory, true},
		{"Payload/App.app/Frameworks/Core.framework", Modified, KindDirectory, true},
	}

	for _, tt := range tests {
		n := findNode(result.Root, tt.path)
		if n == nil {
			t.Errorf("node %q not found in tree", tt.path)
			continue
		}
		if n.Status != tt.status {
			t.Errorf("node %q: status = %v, want %v", tt.path, n.Status, tt.status)
		}
		if n.Kind != tt.kind {
			t.Errorf("node %q: kind = %v, want %v", tt.path, n.Kind, tt.kind)
		}
		if n.IsDir != tt.isDir {
			t.Errorf("node %q: is_dir = %v, want %v", tt.path, n.IsDir, tt.isDir)
		}
	}

	// --- Size checks for the main binary ---
	appBin := findNode(result.Root, "Payload/App.app/App")
	if appBin != nil {
		if appBin.SizeA != 16816 {
			t.Errorf("App binary size_a = %d, want 16816", appBin.SizeA)
		}
		if appBin.SizeB != 16864 {
			t.Errorf("App binary size_b = %d, want 16864", appBin.SizeB)
		}
		if appBin.SizeDelta() != 48 {
			t.Errorf("App binary size_delta = %d, want 48", appBin.SizeDelta())
		}
	}

	// --- NewFeature binary should have zero size_a (added) ---
	nf := findNode(result.Root, "Payload/App.app/Frameworks/NewFeature.framework/NewFeature")
	if nf != nil {
		if nf.SizeA != 0 {
			t.Errorf("NewFeature size_a = %d, want 0", nf.SizeA)
		}
		if nf.SizeB != 16840 {
			t.Errorf("NewFeature size_b = %d, want 16840", nf.SizeB)
		}
	}
}

// assertDirSizesAreAggregated checks that every directory node's size equals
// the sum of its children's sizes, not the filesystem metadata size.
func assertDirSizesAreAggregated(t *testing.T, root *Node) {
	t.Helper()
	var check func(*Node)
	check = func(n *Node) {
		if !n.IsDir || len(n.Children) == 0 {
			return
		}
		var childSumA, childSumB int64
		for _, c := range n.Children {
			childSumA += c.SizeA
			childSumB += c.SizeB
		}
		if n.SizeA != childSumA {
			t.Errorf("dir %q: size_a = %d, want %d (sum of children)", n.Path, n.SizeA, childSumA)
		}
		if n.SizeB != childSumB {
			t.Errorf("dir %q: size_b = %d, want %d (sum of children)", n.Path, n.SizeB, childSumB)
		}
		for _, c := range n.Children {
			check(c)
		}
	}
	check(root)
}

func TestIntegration_DirectorySizeAggregation(t *testing.T) {
	td := testdataDir(t)
	pathA := filepath.Join(td, "app-v1")
	pathB := filepath.Join(td, "app-v2")

	result, err := Compare(pathA, pathB, "")
	if err != nil {
		t.Fatalf("Compare: %v", err)
	}

	assertDirSizesAreAggregated(t, result.Root)
}

func TestIntegration_ArchiveDiff(t *testing.T) {
	td := testdataDir(t)
	pathA := filepath.Join(td, "app-v1.ipa")
	pathB := filepath.Join(td, "app-v2.ipa")

	result, err := Compare(pathA, pathB, "")
	if err != nil {
		t.Fatalf("Compare: %v", err)
	}

	if result.Mode != "tree" {
		t.Fatalf("mode = %q, want tree", result.Mode)
	}

	// The archive diff should produce the same logical result as the directory diff.
	s := result.Summary
	if s.Added != 2 {
		t.Errorf("summary.added = %d, want 2", s.Added)
	}
	if s.Removed != 0 {
		t.Errorf("summary.removed = %d, want 0", s.Removed)
	}
	if s.Modified != 4 {
		t.Errorf("summary.modified = %d, want 4", s.Modified)
	}
	if s.Unchanged != 1 {
		t.Errorf("summary.unchanged = %d, want 1", s.Unchanged)
	}

	// Verify archive correctly detects Mach-O kind inside framework
	core := findNode(result.Root, "Payload/App.app/Frameworks/Core.framework/Core")
	if core == nil {
		t.Fatal("Core binary not found in archive diff tree")
	}
	if core.Kind != KindMachO {
		t.Errorf("Core kind = %v, want macho", core.Kind)
	}
	if core.Status != Modified {
		t.Errorf("Core status = %v, want modified", core.Status)
	}
}

func TestIntegration_AutoDetect_IPA(t *testing.T) {
	td := testdataDir(t)
	pathA := filepath.Join(td, "app-v1.ipa")
	pathB := filepath.Join(td, "app-v2.ipa")

	mode, err := detectMode(pathA, pathB)
	if err != nil {
		t.Fatalf("detectMode: %v", err)
	}
	if mode != "tree" {
		t.Errorf("mode = %q, want tree", mode)
	}
}

func TestIntegration_PlistDetail(t *testing.T) {
	td := testdataDir(t)
	pathA := filepath.Join(td, "app-v1")
	pathB := filepath.Join(td, "app-v2")

	result, err := Compare(pathA, pathB, "")
	if err != nil {
		t.Fatalf("Compare: %v", err)
	}

	// App Info.plist: CFBundleVersion 1.0→2.0, CFBundleShortVersionString added
	plist := findNode(result.Root, "Payload/App.app/Info.plist")
	if plist == nil {
		t.Fatal("App Info.plist not found")
	}

	detail, err := Detail(result, plist)
	if err != nil {
		t.Fatalf("Detail: %v", err)
	}

	found := make(map[string]DiffStatus)
	values := make(map[string]PlistChange)
	for _, c := range detail.Plist.Changes {
		found[c.KeyPath] = c.Status
		values[c.KeyPath] = c
	}

	if found["CFBundleVersion"] != Modified {
		t.Errorf("CFBundleVersion: %v, want modified", found["CFBundleVersion"])
	}
	if v := values["CFBundleVersion"]; v.ValueA != "1.0" || v.ValueB != "2.0" {
		t.Errorf("CFBundleVersion values = (%q, %q), want (1.0, 2.0)", v.ValueA, v.ValueB)
	}
	if found["CFBundleShortVersionString"] != Added {
		t.Errorf("CFBundleShortVersionString: %v, want added", found["CFBundleShortVersionString"])
	}
	if _, ok := found["CFBundleName"]; ok {
		t.Error("CFBundleName should not appear (unchanged)")
	}

	// Core Info.plist: unchanged - Detail should show no changes.
	corePlist := findNode(result.Root, "Payload/App.app/Frameworks/Core.framework/Info.plist")
	if corePlist == nil {
		t.Fatal("Core Info.plist not found")
	}
	if corePlist.Status != Unchanged {
		t.Fatalf("Core Info.plist status = %v, want unchanged", corePlist.Status)
	}
}

func TestIntegration_PlistDetail_Archive(t *testing.T) {
	td := testdataDir(t)
	pathA := filepath.Join(td, "app-v1.ipa")
	pathB := filepath.Join(td, "app-v2.ipa")

	result, err := Compare(pathA, pathB, "")
	if err != nil {
		t.Fatalf("Compare: %v", err)
	}

	plist := findNode(result.Root, "Payload/App.app/Info.plist")
	if plist == nil {
		t.Fatal("App Info.plist not found in archive diff")
	}

	detail, err := Detail(result, plist)
	if err != nil {
		t.Fatalf("Detail: %v", err)
	}

	found := make(map[string]DiffStatus)
	for _, c := range detail.Plist.Changes {
		found[c.KeyPath] = c.Status
	}

	if found["CFBundleVersion"] != Modified {
		t.Errorf("CFBundleVersion: %v, want modified", found["CFBundleVersion"])
	}
	if found["CFBundleShortVersionString"] != Added {
		t.Errorf("CFBundleShortVersionString: %v, want added", found["CFBundleShortVersionString"])
	}
}

func TestIntegration_MixedInputs(t *testing.T) {
	td := testdataDir(t)
	// Compare a directory against an IPA - should work as tree mode.
	pathA := filepath.Join(td, "app-v1")
	pathB := filepath.Join(td, "app-v2.ipa")

	result, err := Compare(pathA, pathB, "tree")
	if err != nil {
		t.Fatalf("Compare: %v", err)
	}

	// Should still produce a valid diff.
	if result.Summary.Added+result.Summary.Removed+result.Summary.Modified == 0 {
		t.Error("expected some changes in mixed dir/archive diff")
	}
}

package compare

import (
	"testing"
)

func TestParsePlistXML(t *testing.T) {
	data := []byte(`<?xml version="1.0" encoding="UTF-8"?>
<plist version="1.0">
<dict>
    <key>Name</key>
    <string>App</string>
    <key>Version</key>
    <integer>42</integer>
    <key>Debug</key>
    <true/>
</dict>
</plist>`)

	val, err := parsePlistXML(data)
	if err != nil {
		t.Fatalf("parsePlistXML: %v", err)
	}

	dict, ok := val.(map[string]any)
	if !ok {
		t.Fatalf("expected map, got %T", val)
	}
	if dict["Name"] != "App" {
		t.Errorf("Name = %v, want App", dict["Name"])
	}
	if dict["Version"] != "42" {
		t.Errorf("Version = %v, want 42", dict["Version"])
	}
	if dict["Debug"] != true {
		t.Errorf("Debug = %v, want true", dict["Debug"])
	}
}

func TestParsePlistXML_Nested(t *testing.T) {
	data := []byte(`<?xml version="1.0" encoding="UTF-8"?>
<plist version="1.0">
<dict>
    <key>Outer</key>
    <dict>
        <key>Inner</key>
        <string>value</string>
    </dict>
    <key>Items</key>
    <array>
        <string>a</string>
        <string>b</string>
    </array>
</dict>
</plist>`)

	val, err := parsePlistXML(data)
	if err != nil {
		t.Fatalf("parsePlistXML: %v", err)
	}

	dict := val.(map[string]any)
	outer := dict["Outer"].(map[string]any)
	if outer["Inner"] != "value" {
		t.Errorf("Outer.Inner = %v, want value", outer["Inner"])
	}

	items := dict["Items"].([]any)
	if len(items) != 2 || items[0] != "a" || items[1] != "b" {
		t.Errorf("Items = %v, want [a b]", items)
	}
}

func TestDiffPlistValues_Modified(t *testing.T) {
	a := map[string]any{
		"CFBundleVersion": "1.0",
		"CFBundleName":    "App",
	}
	b := map[string]any{
		"CFBundleVersion":            "2.0",
		"CFBundleName":               "App",
		"CFBundleShortVersionString": "2.0.0",
	}

	changes := diffPlistValues("", a, b)

	want := map[string]DiffStatus{
		"CFBundleName":               Unchanged, // should NOT appear (unchanged)
		"CFBundleShortVersionString": Added,
		"CFBundleVersion":            Modified,
	}

	found := make(map[string]DiffStatus)
	for _, c := range changes {
		found[c.KeyPath] = c.Status
	}

	for key, status := range want {
		if status == Unchanged {
			if _, ok := found[key]; ok {
				t.Errorf("key %q should not appear in changes (unchanged)", key)
			}
			continue
		}
		if found[key] != status {
			t.Errorf("key %q: status = %v, want %v", key, found[key], status)
		}
	}

	// Check values on the modified key.
	for _, c := range changes {
		if c.KeyPath == "CFBundleVersion" {
			if c.ValueA != "1.0" || c.ValueB != "2.0" {
				t.Errorf("CFBundleVersion values = (%q, %q), want (1.0, 2.0)", c.ValueA, c.ValueB)
			}
		}
	}
}

func TestDiffPlistValues_AddedRemoved(t *testing.T) {
	a := map[string]any{"removed": "old"}
	b := map[string]any{"added": "new"}

	changes := diffPlistValues("", a, b)

	found := make(map[string]DiffStatus)
	for _, c := range changes {
		found[c.KeyPath] = c.Status
	}

	if found["removed"] != Removed {
		t.Errorf("removed: status = %v, want removed", found["removed"])
	}
	if found["added"] != Added {
		t.Errorf("added: status = %v, want added", found["added"])
	}
}

func TestDiffPlistValues_NestedDict(t *testing.T) {
	a := map[string]any{
		"NSAppTransportSecurity": map[string]any{
			"NSAllowsArbitraryLoads": true,
		},
	}
	b := map[string]any{
		"NSAppTransportSecurity": map[string]any{
			"NSAllowsArbitraryLoads": false,
		},
	}

	changes := diffPlistValues("", a, b)
	if len(changes) != 1 {
		t.Fatalf("expected 1 change, got %d: %+v", len(changes), changes)
	}
	c := changes[0]
	if c.KeyPath != "NSAppTransportSecurity.NSAllowsArbitraryLoads" {
		t.Errorf("key_path = %q, want NSAppTransportSecurity.NSAllowsArbitraryLoads", c.KeyPath)
	}
	if c.Status != Modified {
		t.Errorf("status = %v, want modified", c.Status)
	}
}

func TestDiffPlistValues_Array(t *testing.T) {
	a := map[string]any{
		"items": []any{"a", "b"},
	}
	b := map[string]any{
		"items": []any{"a", "c", "d"},
	}

	changes := diffPlistValues("", a, b)

	found := make(map[string]DiffStatus)
	for _, c := range changes {
		found[c.KeyPath] = c.Status
	}

	// items[0] unchanged (not in changes), items[1] modified, items[2] added
	if _, ok := found["items[0]"]; ok {
		t.Error("items[0] should not appear (unchanged)")
	}
	if found["items[1]"] != Modified {
		t.Errorf("items[1]: status = %v, want modified", found["items[1]"])
	}
	if found["items[2]"] != Added {
		t.Errorf("items[2]: status = %v, want added", found["items[2]"])
	}
}

func TestDiffPlistValues_Identical(t *testing.T) {
	a := map[string]any{"key": "same"}
	b := map[string]any{"key": "same"}

	changes := diffPlistValues("", a, b)
	if len(changes) != 0 {
		t.Errorf("expected no changes for identical plists, got %d", len(changes))
	}
}

func TestFormatPlistValue(t *testing.T) {
	tests := []struct {
		input any
		want  string
	}{
		{"hello", "hello"},
		{true, "true"},
		{false, "false"},
		{map[string]any{"a": 1, "b": 2}, "<dict: 2 keys>"},
		{[]any{"x", "y", "z"}, "<array: 3 items>"},
