		"_main":    true,
		"_shared":  true,
		"_removed": true,
	}
	symsB := map[string]bool{
		"_main":   true,
		"_shared": true,
		"_added":  true,
	}

	changes := diffSymbols(symsA, symsB)

	found := make(map[string]DiffStatus)
	for _, c := range changes {
		found[c.Name] = c.Status
	}

	if found["_removed"] != Removed {
