// findNodeInTree searches the tree for a node by name (breadth-first).
func findNodeInTree(root *Node, name string) *Node {
	if root.Name == name {
		return root
	}
	for _, c := range root.Children {
		if found := findNodeInTree(c, name); found != nil {
			return found
		}
	}
	return nil
}

